-- Check overlap between scanprocessing and scanmesh equiprefs
SELECT COUNT(*) as matching FROM (
    SELECT sp.equipref FROM scanprocessing sp
    INTERSECT
    SELECT sm.equipref FROM scanmesh sm
) t;

-- Maybe it's a UNION of different scan types per equipment?
SELECT COUNT(*) FROM (
    SELECT equipref, 'processing' as type FROM scanprocessing
    UNION ALL
    SELECT equipref, 'mesh' as type FROM scanmesh
) x;

-- Maybe they want each processing record but with avg PRU computed per equipref
SELECT COUNT(*) FROM (
    SELECT sp.flowregistry, sp.equipref, sp.flowhrs
    FROM scanprocessing sp
) x;

